{"command":"python3 - << 'PY'
import subprocess, os, base64, zlib, json, shutil
BASE="/tmp/testhome2"
def run(args, cwd="/tmp/proj", env_extra=None, inp=None):
    e=dict(os.environ)
    e.update({"HOME":BASE,"XDG_CONFIG_HOME":BASE+"/.config","XDG_DATA_HOME":BASE+"/.local/share","XDG_CACHE_HOME":BASE+"/.cache"})
    for k in list(e):
        if k.startswith("DIRENV_"): del e[k]
    if env_extra: e.update(env_extra)
    return subprocess.run(["/workspace/executable"]+args, cwd=cwd, env=e, capture_output=True, text=True, input=inp)
def decode(s):
    d=base64.urlsafe_b64decode(s)
    return zlib.decompress(d)

for args in [["dump"], ["dump","json"], ["dump","bash"], ["dump","gzenv"], ["dump","bogus"]]:
    r=run(args, env_extra={"FOO":"bar baz","EMPTY":""})
    print(args, r.returncode, r.stderr[:200])
    if args[-1] in ("json",) or len(args)==1:
        try: print(decode(r.stdout.strip())[:2000])
        except Exception as ex: print("decode fail", ex, r.stdout[:200])
    else:
        print(r.stdout[:2000])

# show_dump
r=run(["dump"])
dump=r.stdout.strip()
r2=run(["show_dump", dump])
print("show_dump dump", r2.stdout, r2.stderr, r2.returncode)
r2=run(["show_dump", "bogus!!!"])
print("show_dump bogus", r2.stdout, r2.stderr, r2.returncode)
r2=run(["show_dump"])
print("show_dump noarg", r2.stdout, r2.stderr, r2.returncode)

# apply_dump
import tempfile
r=run(["dump","json"])  # wait dump json returns?
print("dump json stdout decode attempt", r.stdout[:500])
PY"}

