import subprocess, os, pathlib
BASE="/tmp/testhome2"
cfg=pathlib.Path(BASE+"/.config/direnv/direnv.toml")
def run(args, cwd="/tmp/proj", env_extra=None):
    e=dict(os.environ); e.update({"HOME":BASE,"XDG_CONFIG_HOME":BASE+"/.config","XDG_DATA_HOME":BASE+"/.local/share","XDG_CACHE_HOME":BASE+"/.cache"})
    for k in list(e):
        if k.startswith("DIRENV_"): del e[k]
    if env_extra: e.update(env_extra)
    return subprocess.run(["/workspace/executable"]+args, cwd=cwd, env=e, capture_output=True, text=True)
for toml in [None, '[global]\nwarn_timeout="5s"\n', '[global]\nlog_format=""\n', '[whitelist]\nprefix=[]\n']:
    if toml is None: cfg.unlink(missing_ok=True)
    else: cfg.write_text(toml)
    for typ in ["--status","--error"]:
        r=run(["log",typ,"hi"])
        print(toml, typ, repr(r.stderr))
# errors from main: e.g., bogus command - what format when log_format set?
cfg.write_text('[global]\nlog_format="X %s"\n')
r=run(["bogus"])
print("bogus err with format X", repr(r.stderr))
r=run(["export","bash"], cwd="/tmp/proj")  # loading messages?
print("export loading", repr(r.stderr), repr(r.stdout[:200]))
cfg.unlink(missing_ok=True)
# Check color when TERM=dumb? NO_COLOR?
for env in [{"TERM":"dumb"},{"NO_COLOR":"1"},{"CLICOLOR":"0"}]:
    r=run(["log","--status","hi"], env_extra=env)
    print(env, repr(r.stderr))
    r=run(["bogus"], env_extra=env)
    print(" bogus", repr(r.stderr))
PY"}

