def run(args, cwd="/tmp/proj"):
    e=dict(os.environ); e.update({"HOME":BASE,"XDG_CONFIG_HOME":BASE+"/.config","XDG_DATA_HOME":BASE+"/.local/share","XDG_CACHE_HOME":BASE+"/.cache"})
    for k in list(e):
        if k.startswith("DIRENV_"): del e[k]
    return subprocess.run(["/workspace/executable"]+args, cwd=cwd, env=e, capture_output=True, text=True)
cfgdir=pathlib.Path(BASE+"/.config/direnv")
for name,content in [(None,None),("direnv.toml",""),("config.toml",""),("direnv.toml",'[global]\nlog_format="direnv: %s"\n'),("direnv.toml",'[global]\nlog_format="direnv: %%s"\n')]:
    for p in cfgdir.iterdir(): p.unlink()
    if name: (cfgdir/name).write_text(content)
    r=run(["log","--status","hi"])
    print(name,content, repr(r.stderr))
    r=run(["log","--error","hi"])
    print(" err", repr(r.stderr))
for p in cfgdir.iterdir(): p.unlink()
# DIRENV_CONFIG pointing to empty dir vs with empty file
import os
os.makedirs("/tmp/alt2", exist_ok=True)
for f in pathlib.Path("/tmp/alt2").iterdir(): f.unlink()
def run2():
    e=dict(os.environ); e.update({"HOME":BASE,"XDG_CONFIG_HOME":BASE+"/.config","XDG_DATA_HOME":BASE+"/.local/share","XDG_CACHE_HOME":BASE+"/.cache","DIRENV_CONFIG":"/tmp/alt2"})
    for k in list(e):
        if k.startswith("DIRENV_") and k!="DIRENV_CONFIG": del e[k]
    return subprocess.run(["/workspace/executable","log","--status","hi"], cwd="/tmp/proj", env=e, capture_output=True, text=True)
print("alt no file", repr(run2().stderr))
pathlib.Path("/tmp/alt2/direnv.toml").write_text("")
print("alt empty file", repr(run2().stderr))
PY

