package cmd

import (
	"fmt"
	"os"
	"regexp"
	"strings"
)

var statusLogFormat = "\x1b[0mdirenv: %s"
var errorLogFormat = "\x1b[31mdirenv: %s\x1b[0m"
var logFilterRe *regexp.Regexp
var debugEnabled = false

func initLogging(env Env) {
	v := env["DIRENV_DEBUG"]
	debugEnabled = v == "1" || strings.EqualFold(v, "true")
}

func setupLogging(cfg *Config, configFileExisted bool) error {
	if cfg.logFilter != "" {
		re, err := regexp.Compile(cfg.logFilter)
		if err != nil {
			return fmt.Errorf("error in log filter: %w", err)
		}
		logFilterRe = re
	} else {
		logFilterRe = nil
	}
	if !configFileExisted {
		return nil
	}
	if cfg.logFormat != "" {
		statusLogFormat = cfg.logFormat
	} else {
		statusLogFormat = "direnv: %s"
	}
	errorLogFormat = "direnv: %s"
	return nil
}

func logStatus(format string, args ...interface{}) {
	msg := fmt.Sprintf(format, args...)
	if logFilterRe != nil && !logFilterRe.MatchString(msg) {
		return
	}
	if statusLogFormat == "-" {
		return
	}
	formatted := fmt.Sprintf(statusLogFormat+"\n", msg)
	// NOTE: intentionally mirrors the original formatting pipeline:
	// the already-formatted string is used as the Fprintf format.
	fmt.Fprintf(os.Stderr, formatted)
}

func logError(format string, args ...interface{}) {
	msg := fmt.Sprintf(format, args...)
	formatted := fmt.Sprintf(errorLogFormat+"\n", msg)
	fmt.Fprintf(os.Stderr, formatted)
}

func debugLogf(format string, args ...interface{}) {
	if !debugEnabled {
		return
	}
	// Best-effort debug output; timestamps and call sites are produced by
	// callers that care, this helper keeps a simple direnv-prefixed form.
	msg := fmt.Sprintf(format, args...)
	fmt.Fprintf(os.Stderr, "direnv: %s\n", msg)
}
