func (env Env) toGoEnv() []string {
	out := make([]string, 0, len(env))
	for k, v := range env {
		out = append(out, k+"="+v)
	}
	return out
}

func (env Env) serializeToShell(shell Shell) string {
	return env.ToShell(shell)
}

// ToShell formats the whole environment for the given shell. For special
// shells (JSON-like, gzenv) a map with string values is encoded.
func (env Env) ToShell(shell Shell) string {
	// This call is first so that a nil shell panics in the same way the
	// original did for the private dotenv command.
	kind := shell.Name()
	m := make(map[string]*string, len(env))
	for k, v := range env {
		vv := v
		m[k] = &vv
	}
	return shellEnvToShell(kind, shell, m)
}

