{"command":"cat > internal/cmd/shell.go <<'EOF'
package cmd

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"regexp"
	"strings"
)

type Shell interface {
	Name() string
	Export(key, value string) string
	Remove(key string) string
	Hook(selfPath string) (string, error)
}

type namedShell string

func (s namedShell) Name() string { return string(s) }

var shells = map[string]Shell{
	"bash":    namedShell("bash"),
	"zsh":     namedShell("zsh"),
	"fish":    namedShell("fish"),
	"tcsh":    namedShell("tcsh"),
	"elvish":  namedShell("elvish"),
	"pwsh":    namedShell("pwsh"),
	"murex":   namedShell("murex"),
	"json":    namedShell("json"),
	"vim":     namedShell("vim"),
	"gha":     namedShell("gha"),
	"gzenv":   namedShell("gzenv"),
	"systemd": namedShell("systemd"),
}

func shellFromName(name string) (Shell, error) {
	if sh, ok := shells[name]; ok {
		return sh, nil
	}
	return nil, fmt.Errorf("unknown target shell '%s'", name)
}

// shellFromNameNoErr mirrors the lookup used by the dotenv command: unknown
// shells come back as a nil Shell.
func shellFromNameNoErr(name string) Shell {
	return shells[name]
}

func shellNames() []string {
	out := make([]string, 0, len(shells))
	for k := range shells {
		out = append(out, k)
	}
	return out
}

var bashSafeRe = regexp.MustCompile(`^[A-Z0-9_.,/@-]+$`)

func bashEscape(str string) string {
	if str == "" {
		return "''"
	}
	if bashSafeRe.MatchString(str) {
		return str
	}
	var sb strings.Builder
	sb.WriteString("$'")
	for i := 0; i < len(str); i++ {
		b := str[i]
		switch b {
		case '\\':
			sb.WriteString("\\\\")
		case '\'':
			sb.WriteString("\\'")
		case '\n':
			sb.WriteString("\\n")
		case '\r':
			sb.WriteString("\\r")
		case '\t':
			sb.WriteString("\\t")
		default:
			if b < 32 || b > 126 {
				fmt.Fprintf(&sb, "\\x%02x", b)
			} else {
				sb.WriteByte(b)
			}
		}
	}
	sb.WriteString("'")
	return sb.String()
}

func fishEscape(str string) string {
	var sb strings.Builder
	sb.WriteString("'")
	for i := 0; i < len(str); i++ {
		b := str[i]
		switch b {
		case '\'':
			sb.WriteString("\\'")
		case '\\':
			sb.WriteString("\\\\")
		case '\n':
			sb.WriteString("'\\n'")
		case '\r':
			sb.WriteString("'\\r'")
		case '\t':
			sb.WriteString("'\\t'")
		default:
			if b < 32 || b > 126 {
				fmt.Fprintf(&sb, "'\\X%02x'", b)
			} else {
				sb.WriteByte(b)
			}
		}
	}
	sb.WriteString("'")
	return sb.String()
}

const tcshSpecial = "!\"#$%&()*+:;<>?[{|}~"

func tcshEscape(str string) string {
	if str == "" {
		return "''"
	}
	var sb strings.Builder
	for i := 0; i < len(str); i++ {
		b := str[i]
		switch {
		case b == '\\':
			sb.WriteString("\\\\")
		case b == '\'':
			sb.WriteString("\\'")
		case b == ' ':
			sb.WriteString("\\ ")
		case b == '\n':
			sb.WriteString("\\n")
		case b == '\r':
			sb.WriteString("\\r")
		case b == '\t':
			sb.WriteString("\\t")
		case b < 32 || b > 126:
			fmt.Fprintf(&sb, "\\x%02x", b)
		case strings.ContainsRune(tcshSpecial, rune(b)):
			sb.WriteByte('"')
			sb.WriteByte(b)
			sb.WriteByte('"')
		default:
			sb.WriteByte(b)
		}
	}
	return sb.String()
}

func pwshEscape(str string) string {
	return "'" + strings.ReplaceAll(str, "'", "''") + "'"
}

func vimEscape(str string) string {
	s := strings.ReplaceAll(str, "'", "''")
	s = strings.ReplaceAll(s, "\n", "\\n")
	return "'" + s + "'"
}

func systemdEscape(str string) string {
	if strings.ContainsAny(str, "\n'\"\\") {
		s := strings.ReplaceAll(str, "\\", "\\\\")
		s = strings.ReplaceAll(s, "\"", "\\\"")
		return "\"" + s + "\""
	}
	return str
}

func (s namedShell) Export(key, value string) string {
	switch string(s) {
	case "bash", "zsh":
		return "export " + bashEscape(key) + "=" + bashEscape(value) + ";"
	case "fish":
		if key == "PATH" {
			parts := strings.Split(value, ":")
			esc := make([]string, 0, len(parts))
			for _, p := range parts {
				esc = append(esc, fishEscape(p))
			}
			return "set -x -g PATH " + strings.Join(esc, " ") + ";"
		}
		return "set -x -g " + fishEscape(key) + " " + fishEscape(value) + ";"
	case "tcsh":
		if key == "PATH" {
			parts := strings.Split(value, ":")
			esc := make([]string, 0, len(parts))
			for _, p := range parts {
				esc = append(esc, tcshEscape(p))
			}
			if value == "" {
				// tcshEscape("") is '', keep consistent with other vars
				esc = []string{tcshEscape("")}
			}
			return "set path = ( " + strings.Join(esc, " ") + " );"
		}
		return "setenv " + key + " " + tcshEscape(value) + " ;"
	case "pwsh":
		return "${env:" + key + "}=" + pwshEscape(value) + ";"
	case "vim":
		return "call setenv(" + vimEscape(key) + "," + vimEscape(value) + ")\n"
	case "gha":
		var rnd [16]byte
		_, _ = rand.Read(rnd[:])
		delim := "ghadelimiter_" + hex.EncodeToString(rnd[:])
		return fmt.Sprintf("%s<<%s\n%s\n%s\n", key, delim, value, delim)
	case "systemd":
		return key + "=" + systemdEscape(value) + "\n"
	default:
		// JSON-ish and gzenv shells are handled at the map level; this is
		// only a fallback.
		return ""
	}
}

func (s namedShell) Remove(key string) string {
	switch string(s) {
	case "bash", "zsh":
		return "unset " + bashEscape(key) + ";"
	case "fish":
		return "set -e -g " + fishEscape(key) + ";"
	case "tcsh":
		return "unsetenv " + key + " ;"
	case "pwsh":
		return "Remove-Item -LiteralPath 'env:/" + key + "';"
	case "vim":
		return "call setenv(" + vimEscape(key) + ",v:null)\n"
	case "gha", "systemd":
		return ""
	default:
		return ""
	}
}

func shellEnvToShell(kind string, shell Shell, m map[string]*string) string {
	switch kind {
	case "json":
		b, _ := json.MarshalIndent(m, "", "  ")
		return string(b)
	case "elvish", "murex":
		b, _ := json.Marshal(m)
		return string(b) + "\n"
	case "gzenv":
		b, _ := json.Marshal(m)
		enc, _ := marshalRaw(b)
		return enc
	default:
		var sb strings.Builder
		for k, v := range m {
			if v == nil {
