	switch string(s) {
	case "bash", "zsh":
		return "unset " + bashEscape(key) + ";"
	case "fish":
		return "set -e -g " + fishEscape(key) + ";"
	case "tcsh":
		return "unsetenv " + key + " ;"
	case "pwsh":
		return "Remove-Item -LiteralPath 'env:/" + key + "';"
	case "vim":
		return "call setenv(" + vimEscape(key) + ",v:null)\n"
	case "gha", "systemd":
		return ""
	default:
		return ""
	}
}

func shellEnvToShell(kind string, shell Shell, m map[string]*string) string {
	switch kind {
	case "json":
		b, _ := json.MarshalIndent(m, "", "  ")
		return string(b)
	case "elvish", "murex":
		b, _ := json.Marshal(m)
		return string(b) + "\n"
	case "gzenv":
		b, _ := json.Marshal(m)
		enc, _ := marshalRaw(b)
		return enc
	default:
		var sb strings.Builder
		for k, v := range m {
			if v == nil {
				sb.WriteString(shell.Remove(k))
			} else {
				sb.WriteString(shell.Export(k, *v))
			}
		}
		return sb.String()
	}
}

