package cmd

import (
	"fmt"
	"sort"
	"strings"
)

type EnvDiff struct {
	Prev Env `json:"p"`
	Next Env `json:"n"`
}

var ignoredKeys = map[string]bool{
	"_":                 true,
	"PWD":               true,
	"OLDPWD":            true,
	"SHLVL":             true,
	"PS1":               true,
	"SHELL":             true,
	"COMP_WORDBREAKS":   true,
	"REPLY":             true,
	"DIRENV_BASH":       true,
	"DIRENV_CONFIG":     true,
	"DIRENV_IN_ENVRC":   true,
}

func isIgnoredKey(k string) bool { return ignoredKeys[k] }

func diffEnv(oldEnv, newEnv Env) EnvDiff {
	diff := EnvDiff{Prev: make(Env), Next: make(Env)}
	for k, v := range oldEnv {
		if isIgnoredKey(k) {
			continue
		}
		if nv, ok := newEnv[k]; !ok {
			diff.Prev[k] = v
		} else if nv != v {
			diff.Prev[k] = v
			diff.Next[k] = nv
		}
	}
	for k, v := range newEnv {
		if isIgnoredKey(k) {
			continue
		}
		if _, ok := oldEnv[k]; !ok {
			diff.Next[k] = v
		}
	}
	return diff
}

func (diff EnvDiff) toShell(shell Shell) string {
	kind := shell.Name()
	m := make(map[string]*string, len(diff.Next)+len(diff.Prev))
	for k, v := range diff.Next {
		vv := v
		m[k] = &vv
	}
	for k := range diff.Prev {
		if _, ok := diff.Next[k]; !ok {
			m[k] = nil
		}
	}
	return shellEnvToShell(kind, shell, m)
}

func (diff EnvDiff) serialize() string {
	s, _ := marshal(diff)
	return s
}

func (diff EnvDiff) String() string {
	var added, removed, changed []string
	for k, v := range diff.Next {
		if strings.HasPrefix(k, "DIRENV_") {
			continue
		}
		if pv, ok := diff.Prev[k]; !ok {
			added = append(added, k)
		} else if pv != v {
			changed = append(changed, k)
		}
	}
	for k := range diff.Prev {
		if strings.HasPrefix(k, "DIRENV_") {
			continue
		}
		if _, ok := diff.Next[k]; !ok {
			removed = append(removed, k)
		}
	}
	sort.Strings(added)
	sort.Strings(removed)
	sort.Strings(changed)
	var parts []string
	for _, k := range added {
		parts = append(parts, "+"+k)
	}
	for _, k := range removed {
		parts = append(parts, "-"+k)
	}
	for _, k := range changed {
		parts = append(parts, "~"+k)
	}
	return strings.Join(parts, " ")
}

// revert returns the environment before this diff was applied, starting
// from an environment that has the diff applied.
func (env Env) revertDiff(diff EnvDiff) Env {
	out := env.copy()
	for k := range diff.Next {
		delete(out, k)
	}
	for k, v := range diff.Prev {
		out[k] = v
	}
	return out
}

func revertEnv(env Env) (Env, error) {
	diffStr, ok := env["DIRENV_DIFF"]
	if !ok || diffStr == "" {
		return env.copy(), nil
	}
	var diff EnvDiff
	if err := unmarshal(diffStr, &diff); err != nil {
		return nil, fmt.Errorf("Revert() failed: %w", err)
	}
	if diff.Prev == nil {
		diff.Prev = make(Env)
	}
	if diff.Next == nil {
		diff.Next = make(Env)
	}
	return env.revertDiff(diff), nil
}

// revertEnvPlain is used by exec: errors are not wrapped.
func revertEnvPlain(env Env) (Env, error) {
	diffStr, ok := env["DIRENV_DIFF"]
	if !ok || diffStr == "" {
		return env.copy(), nil
	}
	var diff EnvDiff
	if err := unmarshal(diffStr, &diff); err != nil {
		return nil, err
	}
