	if err != nil {
		return filepath.Clean(path)
	}
	return abs
}

func (times *FileTimes) update(path string, modTime int64, exists bool) {
	abs := absPath(path)
	if times.list == nil {
		l := []FileTime{}
		times.list = &l
	}
	for i := range *times.list {
		if (*times.list)[i].Path == abs {
			(*times.list)[i].ModTime = modTime
			(*times.list)[i].Exists = exists
			return
		}
	}
	*times.list = append(*times.list, FileTime{Path: abs, ModTime: modTime, Exists: exists})
}

func (times *FileTimes) updateFromFile(path string) {
	ft := getFileTime(absPath(path))
	times.update(ft.Path, ft.ModTime, ft.Exists)
}

func (ft FileTime) check() error {
	mt, ok := getLatestStat(ft.Path)
	if !ok {
		if ft.Exists {
			debugLogf("Stat Check: %s: gone", ft.Path)
			return fmt.Errorf("File %q is missing (Stat)", ft.Path)
		}
		debugLogf("Check: %s: up to date", ft.Path)
		return nil
	}
	if !ft.Exists {
		debugLogf("Check: %s: appeared", ft.Path)
		return fmt.Errorf("File %q newly created", ft.Path)
	}
	if mt != ft.ModTime {
		debugLogf("Check: %s: stale (stat: %d, lastcheck: %d)", ft.Path, mt, ft.ModTime)
		return fmt.Errorf("File %q has changed", ft.Path)
	}
	debugLogf("Check: %s: up to date", ft.Path)
	return nil
}

func (times FileTimes) check() error {
	for _, ft := range times.slice() {
		if err := ft.check(); err != nil {
			return err
		}
	}
	return nil
}

func (times FileTimes) find(path string) (FileTime, bool) {
	for _, ft := range times.slice() {
		if ft.Path == path {
			return ft, true
		}
	}
	return FileTime{}, false
}
EOF
"}

