}

func loadConfig(env Env) (*Config, error) {
	configDir, err := getConfigDir(env)
	if err != nil {
		return nil, err
	}
	cacheDir, err := getCacheDir(env)
	if err != nil {
		return nil, err
	}
	dataDir, err := getDataDir(env)
	if err != nil {
		return nil, err
	}
	cfg := &Config{
		ConfigDir:       configDir,
		SelfPath:        selfPath(),
		warnTimeout:     5 * time.Second,
		cacheDir:        cacheDir,
		dataDir:         dataDir,
		whitelistPrefix: []string{},
		whitelistExact:  map[string]bool{},
	}

