		if md.IsDefined("global", "strict_env") {
			cfg.strictEnv = g.StrictEnv
		}
		if md.IsDefined("global", "load_dotenv") {
			cfg.loadDotEnv = g.LoadDotEnv
		}
		if md.IsDefined("global", "warn_timeout") {
			cfg.warnTimeout = g.WarnTimeout
		}
		if md.IsDefined("global", "hide_env_diff") {
			cfg.hideEnvDiff = g.HideEnvDiff
		}
		if md.IsDefined("global", "log_format") {
			cfg.logFormat = g.LogFormat
		}
		if md.IsDefined("global", "log_filter") {
			cfg.logFilter = g.LogFilter
		}
		// Whitelist
		cfg.whitelistPrefix = []string{}
		for _, p := range parsed.Whitelist.Prefix {
			if strings.HasPrefix(p, "~/") {
				home := env["HOME"]
				p = filepath.Join(home, p[2:])
			}
			cfg.whitelistPrefix = append(cfg.whitelistPrefix, p)
		}
		cfg.whitelistExact = map[string]bool{}
		for _, e := range parsed.Whitelist.Exact {
			expanded := expandTilde(e, env)
			if !strings.HasSuffix(expanded, "/.envrc") && !strings.HasSuffix(expanded, "/.env") {
				expanded = filepath.Join(expanded, ".envrc")
			}
			cfg.whitelistExact[expanded] = true
		}
		if err := setupLogging(cfg, true); err != nil {
			return nil, err
		}
	}

	if v, ok := env["DIRENV_WARN_TIMEOUT"]; ok && v != "" {
		d, err := time.ParseDuration(v)
		if err != nil {
			logError("invalid DIRENV_WARN_TIMEOUT: %s", err.Error())
		} else {
			cfg.warnTimeout = d
		}
	}

	if cfg.bashPath == "" {
		if v, ok := env["DIRENV_BASH"]; ok && v != "" {
			cfg.bashPath = v
		} else {
			bash, err := exec.LookPath("bash")
			if err != nil {
				return nil, fmt.Errorf("can't find bash: %w", err)
			}
			cfg.bashPath = bash
		}
	}
	return cfg, nil
}

func rewriteTomlErr(s string) string {
	// BurntSushi >= 1.5 phrases invalid durations slightly differently
	// from the version the original was built against.
	s = strings.ReplaceAll(s, "invalid duration: \"", "time: invalid duration \"")
	return s
}

func expandTilde(path string, env Env) string {
	home := env["HOME"]
	if path == "~" {
		return home
	}
	if strings.HasPrefix(path, "~/") {
		return filepath.Join(home, path[2:])
	}
	return path
}

func hashString(s string) string {
	h := sha256.Sum256([]byte(s))
	return hex.EncodeToString(h[:])
}

func fileHashHex(path string, content []byte) string {
	h := sha256.New()
	h.Write([]byte(path))
	h.Write([]byte("\n"))
	h.Write(content)
	return hex.EncodeToString(h.Sum(nil))
}
EOF
"}

