	"fmt"
	"os"
	"path/filepath"
	"strings"
)

type AllowedStatus int

const (
	Allowed    AllowedStatus = 0
	NotAllowed AllowedStatus = 1
	Denied     AllowedStatus = 2
)

type RC struct {
	path      string
	allowPath string
	denyPath  string
	times     FileTimes
	config    *Config
}

func newRC(path string, config *Config, times *FileTimes) *RC {
	content, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	allowPath := filepath.Join(config.dataDir, "allow", fileHashHex(path, content))
	denyPath := filepath.Join(config.dataDir, "deny", hashString(path+"\n"))
	rc := &RC{path: path, allowPath: allowPath, denyPath: denyPath, config: config}
	if times != nil {
		rc.times = *times
	} else {
		l := []FileTime{getFileTime(path), getFileTime(allowPath), getFileTime(denyPath)}
		rc.times = FileTimes{list: &l}
	}
	return rc
}

func (rc *RC) Allowed() AllowedStatus {
	if rc == nil {
		return NotAllowed
	}
	if _, err := os.Stat(rc.denyPath); err == nil {
		return Denied
	}
	if rc.config != nil {
		for _, pre := range rc.config.whitelistPrefix {
			if strings.HasPrefix(rc.path, pre) {
				return Allowed
			}
		}
		if rc.config.whitelistExact[rc.path] {
			return Allowed
		}
	}
	if _, err := os.Stat(rc.allowPath); err == nil {
		return Allowed
	}
	return NotAllowed
}

func (rc *RC) MarshalJSON() ([]byte, error) {
	return json.Marshal(struct {
		Allowed AllowedStatus `json:"allowed"`
		Path    string        `json:"path"`
	}{Allowed: rc.Allowed(), Path: rc.path})
}

func findRC(wd string, config *Config) *RC {
	dir := wd
	for {
		if rc := newRC(filepath.Join(dir, ".envrc"), config, nil); rc != nil {
			return rc
		}
		if config.loadDotEnv {
			if rc := newRC(filepath.Join(dir, ".env"), config, nil); rc != nil {
				return rc
			}
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return nil
		}
		dir = parent
	}
}

func rcFromEnv(env Env, config *Config) *RC {
	path, ok := env["DIRENV_FILE"]
	if !ok || path == "" {
		debugLogf("RCFile is blank - loadedRC is nil")
		return nil
	}
	watchesStr, ok := env["DIRENV_WATCHES"]
	if !ok {
		debugLogf("RCFile is blank - loadedRC is nil")
		return nil
	}
	times, err := unmarshalFileTimes(watchesStr)
	if err != nil {
		debugLogf("RCFile is blank - loadedRC is nil")
		return nil
	}
	// DIRENV_FILE must be absolute for a loaded RC to be recognised
	if !filepath.IsAbs(path) {
		return nil
	}
	return newRC(path, config, &times)
}

func findRCFromArg(arg string, config *Config) (*RC, error) {
	wd, err := os.Getwd()
	if err != nil {
		return nil, err
	}
	searchDir := wd
	if arg != "" {
		abs := absPath(arg)
		info, err := os.Lstat(abs)
		if err != nil {
			return nil, err
		}
		if info.IsDir() {
			searchDir = abs
		} else {
			searchDir = filepath.Dir(abs)
		}
	}
	rc := findRC(searchDir, config)
	if rc == nil {
		return nil, fmt.Errorf(".envrc file not found")
	}
	return rc, nil
}

// buildEmptyEnvLike returns the synthetic env direnv exposes when an RC is
// blocked, denied, or fails to load: the previous env reverted, plus the
// DIRENV_* bookkeeping for the found RC.
func (rc *RC) buildMetaEnv(clean Env) Env {
	out := clean.copy()
	out["DIRENV_DIR"] = "-" + filepath.Dir(rc.path)
	out["DIRENV_FILE"] = rc.path
	// Fresh watches for this RC
	times := FileTimes{}
	l := []FileTime{getFileTime(rc.path), getFileTime(rc.allowPath), getFileTime(rc.denyPath)}
	times.list = &l
	out["DIRENV_WATCHES"] = times.marshalString()
	diff := diffEnv(clean, out)
	out["DIRENV_DIFF"] = diff.serialize()
	return out
}
EOF
"}

