package cmd

import (
	"bytes"
	"encoding/json"
	"fmt"
	osexec "os/exec"
	"path/filepath"
	"strings"
	"time"
)

// loadRCEnv loads rc into a fresh env based on cleanEnv (already reverted).
// It returns the new env; on blocked/load failure it returns the meta env
// together with the error.
func (rc *RC) load(config *Config, cleanEnv Env) (Env, error) {
	switch rc.Allowed() {
	case Denied:
		return rc.buildMetaEnv(cleanEnv), nil
	case NotAllowed:
		return rc.buildMetaEnv(cleanEnv), fmt.Errorf("%s is blocked. Run `direnv allow` to approve its content", rc.path)
	}

	isDotEnv := filepath.Base(rc.path) == ".env"
	if !isDotEnv {
		logStatus("loading %s", rc.path)
	}

	envForBash := cleanEnv.copy()
	envForBash["DIRENV_WATCHES"] = rc.times.marshalString()

	var cmdStr string
	if config.strictEnv {
		cmdStr = "set -euo pipefail && "
	}
	fn := "source_env"
	if isDotEnv {
		fn = "dotenv"
	}
	cmdStr += fmt.Sprintf("eval \"$(\"%s\" stdlib)\" && __main__ %s %s", config.SelfPath, fn, bashEscape(rc.path))

	cmd := osexec.Command(config.bashPath, "-c", cmdStr)
	cmd.Env = envForBash.toGoEnv()
	cmd.Stderr = stderrWriter()
	if config.disableStdin {
		cmd.Stdin = nil
	} else {
		cmd.Stdin = stdinReader()
	}
	var stdout bytes.Buffer
	cmd.Stdout = &stdout

	var timer *time.Timer
	if config.warnTimeout > 0 {
		timer = time.AfterFunc(config.warnTimeout, func() {
			logStatus("([%s]) is taking a while to execute. Use CTRL-C to give up.", strings.Join(osArgs(), " "))
		})
	}
	err := cmd.Run()
	if timer != nil {
		timer.Stop()
	}
	if err != nil {
		return rc.buildMetaEnv(cleanEnv), err
	}

	out := stdout.Bytes()
	newEnv := envForBash.copy()
	if len(bytes.TrimSpace(out)) > 0 {
		var dumped Env
		if jerr := json.Unmarshal(out, &dumped); jerr != nil {
			return rc.buildMetaEnv(cleanEnv), jerr
		}
		newEnv = dumped
		if newEnv == nil {
			newEnv = make(Env)
		}
	}

	// Record the loaded RC in the new env.
	newEnv["DIRENV_DIR"] = "-" + filepath.Dir(rc.path)
	newEnv["DIRENV_FILE"] = rc.path
	// DIRENV_WATCHES is whatever the bash run ended with (initial watches
	// unless watch_file modified it); keep it if present, otherwise seed.
	if _, ok := newEnv["DIRENV_WATCHES"]; !ok {
		newEnv["DIRENV_WATCHES"] = envForBash["DIRENV_WATCHES"]
	}
	diff := diffEnv(cleanEnv, newEnv)
	newEnv["DIRENV_DIFF"] = diff.serialize()
	return newEnv, nil
}
EOF
