{"command":"cat > internal/cmd/cmd_help.go <<'EOF'
package cmd

import (
	"fmt"
	"os"
	"strings"
)

func cmdHelp(env Env, args []string) error {
	showPrivate := len(args) > 0
	fmt.Printf("direnv v%s\n", versionStr)
	fmt.Println("Usage: direnv COMMAND [...ARGS]")
	fmt.Println("")
	fmt.Println("Available commands")
	fmt.Println("------------------")
	for _, c := range commandsList() {
		if c.private && !showPrivate {
			continue
		}
		name := c.usage
		if c.private {
			name = "*" + name
		}
		fmt.Println(name + ":")
		if len(c.aliases) > 0 {
			fmt.Println("  aliases: " + strings.Join(c.aliases, ", "))
		}
		for _, line := range strings.Split(c.description, "\n") {
			fmt.Println("  " + line)
		}
	}
	if showPrivate {
		fmt.Println("* = private commands")
	}
	return nil
}

func cmdVersion(env Env, args []string) error {
	if len(args) == 0 {
		fmt.Println(versionStr)
		return nil
	}
	return checkVersionAtLeast(args[0])
}

func parseSemver(v string) ([]int, string, bool) {
	// Returns numeric components, prerelease suffix handling is done in compare.
	orig := v
	if !strings.HasPrefix(v, "v") {
		v = "v" + v
	}
	_ = orig
	core := v[1:]
	pre := ""
	if idx := strings.Index(core, "-"); idx >= 0 {
		pre = core[idx+1:]
		core = core[:idx]
	}
	if idx := strings.Index(core, "+"); idx >= 0 {
		// build metadata, validated separately
		core = core[:idx]
	}
	parts := strings.Split(core, ".")
