cat > internal/cmd/cmd_status.go <<'EOF'
package cmd

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"time"
)

func cmdStatus(cfg *Config, env Env, args []string) error {
	jsonOut := false
	for _, a := range args {
		if a == "--json" || a == "-json" {
			jsonOut = true
		}
	}
	wd, _ := os.Getwd()
	loadedRC := rcFromEnv(env, cfg)
	var foundRC *RC
	if wd != "" {
		foundRC = findRC(wd, cfg)
	}

	if jsonOut {
		state := struct {
			Config *Config `json:"config"`
			State  struct {
				FoundRC  *RC `json:"foundRC"`
				LoadedRC *RC `json:"loadedRC"`
			} `json:"state"`
		}{Config: cfg}
		state.State.FoundRC = foundRC
		state.State.LoadedRC = loadedRC
		b, err := json.MarshalIndent(state, "", "  ")
		if err != nil {
			return err
		}
		fmt.Println(string(b))
		return nil
	}

	fmt.Println("direnv exec path", cfg.SelfPath)
	fmt.Println("DIRENV_CONFIG", cfg.ConfigDir)
	fmt.Println("bash_path", cfg.bashPath)
	fmt.Println("disable_stdin", cfg.disableStdin)
	fmt.Println("warn_timeout", cfg.warnTimeout.String())
	fmt.Println("whitelist.prefix", cfg.whitelistPrefix)
	fmt.Println("whitelist.exact", cfg.whitelistExact)
	if loadedRC != nil {
		printRCStatus("Loaded", loadedRC)
	} else {
		fmt.Println("No .envrc or .env loaded")
	}
	if foundRC != nil {
		printRCStatus("Found", foundRC)
	} else {
		fmt.Println("No .envrc or .env found")
	}
	return nil
}

func printRCStatus(prefix string, rc *RC) {
	fmt.Println(prefix+" RC path", rc.path)
	rcDir := filepath.Dir(rc.path)
	for _, ft := range rc.times.slice() {
		rel, err := filepath.Rel(rcDir, ft.Path)
		if err != nil {
			rel = ft.Path
		}
		t := time.Unix(ft.ModTime, 0).Format(time.RFC3339)
		fmt.Printf("%s watch: %q - %s\n", prefix, rel, t)
	}
	fmt.Println(prefix+" RC allowed", int(rc.Allowed()))
	fmt.Println(prefix+" RC allowPath", rc.allowPath)
}
EOF
"}

