package cmd

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

func resolveRCForAllow(cfg *Config, args []string) (*RC, error) {
	arg := ""
	if len(args) > 0 {
		arg = args[0]
	}
	if arg == "" {
		wd, err := os.Getwd()
		if err != nil {
			return nil, err
		}
		rc := findRC(wd, cfg)
		if rc == nil {
			return nil, fmt.Errorf(".envrc file not found")
		}
		return rc, nil
	}
	return findRCFromArg(arg, cfg)
}

func cmdAllow(cfg *Config, env Env, args []string) error {
	rc, err := resolveRCForAllow(cfg, args)
	if err != nil {
		return err
	}
	_ = os.Remove(rc.denyPath)
	if err := os.MkdirAll(filepath.Dir(rc.allowPath), 0755); err != nil {
		return err
	}
	if err := os.WriteFile(rc.allowPath, []byte(rc.path+"\n"), 0644); err != nil {
		return err
	}
	// Required files recorded in DIRENV_REQUIRED
	reqStr, ok := env["DIRENV_REQUIRED"]
	if ok && reqStr != "" {
		rcDir := filepath.Dir(rc.path)
		envrcHash := hashString(rc.path + "\n")
		for _, req := range strings.Split(reqStr, ":") {
			full := filepath.Join(rcDir, req)
			if _, err := os.Stat(full); err != nil {
				return fmt.Errorf("required file does not exist: %s", req)
			}
			content, err := os.ReadFile(full)
			if err != nil {
				return fmt.Errorf("failed to hash required file %s: %w", req, err)
			}
			fileHash := fileHashHex(full, content)
			destDir := filepath.Join(cfg.dataDir, "allowed-required", envrcHash)
			if err := os.MkdirAll(destDir, 0755); err != nil {
				return err
			}
			dest := filepath.Join(destDir, fileHash)
			if err := os.WriteFile(dest, []byte(req+"\n"), 0644); err != nil {
				return err
			}
			fmt.Printf("direnv: allowing %s\n", req)
		}
	}
	return nil
}

func cmdBlock(cfg *Config, env Env, args []string) error {
	rc, err := resolveRCForAllow(cfg, args)
	if err != nil {
		return err
	}
	_ = os.Remove(rc.allowPath)
	// Remove allowed-required entries for this envrc
	envrcHash := hashString(rc.path + "\n")
	_ = os.RemoveAll(filepath.Join(cfg.dataDir, "allowed-required", envrcHash))
	if err := os.MkdirAll(filepath.Dir(rc.denyPath), 0755); err != nil {
		return err
	}
	if err := os.WriteFile(rc.denyPath, []byte(rc.path+"\n"), 0644); err != nil {
		return err
	}
	return nil
}

func cmdReload(cfg *Config, env Env, args []string) error {
	wd, err := os.Getwd()
	if err != nil {
		return err
	}
	rc := findRC(wd, cfg)
	if rc == nil {
		return fmt.Errorf(".envrc not found")
	}
	now := timeNow()
	return os.Chtimes(rc.path, now, now)
}
