func cmdPrune(cfg *Config, env Env, args []string) error {
	allowDir := filepath.Join(cfg.dataDir, "allow")
	entries, err := os.ReadDir(allowDir)
	if err != nil {
		return err
	}
	// map from envrc-hash (sha256(path+"\n")) to envrc dir for valid allows
	validRCs := map[string]string{}
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		full := filepath.Join(allowDir, e.Name())
		data, err := os.ReadFile(full)
		if err != nil {
			continue
		}
		rcPath := strings.TrimSpace(string(data))
		if rcPath == "" {
			continue
		}
		content, err := os.ReadFile(rcPath)
		if err != nil {
			_ = os.Remove(full)
			continue
		}
		if fileHashHex(rcPath, content) != e.Name() {
			_ = os.Remove(full)
			continue
		}
		validRCs[hashString(rcPath+"\n")] = filepath.Dir(rcPath)
	}

	reqBase := filepath.Join(cfg.dataDir, "allowed-required")
	reqEntries, err := os.ReadDir(reqBase)
	if err == nil {
		for _, sub := range reqEntries {
			subPath := filepath.Join(reqBase, sub.Name())
			if !sub.IsDir() {
				continue
			}
			rcDir, ok := validRCs[sub.Name()]
			if !ok {
				_ = os.RemoveAll(subPath)
				continue
			}
			files, err := os.ReadDir(subPath)
			if err != nil {
				continue
			}
			for _, f := range files {
				if f.IsDir() {
					continue
				}
				fp := filepath.Join(subPath, f.Name())
				data, err := os.ReadFile(fp)
				if err != nil {
					continue
				}
				rel := strings.TrimSpace(string(data))
				if rel == "" {
					continue
				}
				reqFull := filepath.Join(rcDir, rel)
				content, err := os.ReadFile(reqFull)
				if err != nil {
					_ = os.Remove(fp)
					continue
				}
				if fileHashHex(reqFull, content) != f.Name() {
					_ = os.Remove(fp)
					continue
				}
			}
		}
	}
	var _ = fmt.Sprintf
	return nil
}
EOF
"}

