{"command":"cat > internal/cmd/cmd_exec.go <<'EOF'
package cmd

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"syscall"
)

func cmdExec(cfg *Config, env Env, args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("missing DIR and COMMAND arguments")
	}
	dirArg := args[0]
	info, err := os.Stat(dirArg)
	if err != nil {
		return err
	}
	var dir string
	var command string
	var commandArgs []string
	if info.IsDir() {
		if len(args) < 2 {
			return fmt.Errorf("missing COMMAND argument")
		}
		dir = dirArg
		command = args[1]
		commandArgs = args[1:]
	} else {
		dir = filepath.Dir(dirArg)
		command = dirArg
		commandArgs = args
	}

	absDir := absPath(dir)

	// Compute new env: revert any currently loaded env, then load the
	// RC found in dir (if any).
	clean, err := revertEnvPlain(env)
	if err != nil {
		return err
	}
	newEnv := clean
	if rc := findRC(absDir, cfg); rc != nil {
		loaded, lerr := rc.load(cfg, clean)
		if lerr != nil {
			return lerr
		}
		newEnv = loaded
	} else {
		// No RC: use the reverted (clean) env
		newEnv = clean
	}

	// Look up command using the new env's PATH
	pathVal := newEnv["PATH"]
	binary, err := lookPathIn(command, pathVal)
	if err != nil {
		return fmt.Errorf("command '%s' not found on PATH '%s'", command, pathVal)
	}
	return syscall.Exec(binary, commandArgs, newEnv.toGoEnv())
}

func lookPathIn(file, pathVal string) (string, error) {
	if strings.Contains(file, "/") {
		if isExecutable(file) {
			return file, nil
		}
		return "", fmt.Errorf("not executable")
	}
	for _, dir := range filepath.SplitList(pathVal) {
		if dir == "" {
			dir = "."
		}
		candidate := filepath.Join(dir, file)
		if isExecutable(candidate) {
			return candidate, nil
		}
	}
	return "", fmt.Errorf("not found")
}

func isExecutable(p string) bool {
	info, err := os.Stat(p)
	if err != nil {
		return false
	}
	if info.IsDir() {
		return false
	}
	return info.Mode().Perm()&0111 != 0
}
EOF
"}

