package cmd

import (
	"encoding/json"
	"fmt"
	"os"
)

func cmdDump(env Env, args []string) error {
	shellName := "gzenv"
	filePath := ""
	if len(args) > 0 {
		shellName = args[0]
		if len(args) > 1 {
			filePath = args[1]
		}
	}
	if filePath == "" {
		if v, ok := env["DIRENV_DUMP_FILE_PATH"]; ok {
			filePath = v
		}
	}
	var f *os.File
	if filePath != "" {
		var err error
		f, err = os.OpenFile(filePath, os.O_WRONLY, 0)
		if err != nil {
			return err
		}
		defer f.Close()
	}
	shell, err := shellFromName(shellName)
	if err != nil {
		return err
	}
	out := env.ToShell(shell)
	if f != nil {
		_, err := fmt.Fprintln(f, out)
		return err
	}
	fmt.Println(out)
	return nil
}

func cmdShowDump(env Env, args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("missing DUMP argument")
	}
	var data interface{}
	if err := unmarshal(args[0], &data); err != nil {
		return err
	}
	b, err := json.MarshalIndent(data, "", "  ")
	if err != nil {
		return err
	}
	fmt.Println(string(b))
	return nil
}

func cmdApplyDump(env Env, args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("not enough arguments")
	}
	if len(args) > 1 {
		return fmt.Errorf("too many arguments")
	}
	data, err := os.ReadFile(args[0])
	if err != nil {
		return err
	}
	var dumped Env
	if err := unmarshal(string(data), &dumped); err != nil {
		return err
	}
	if dumped == nil {
		dumped = make(Env)
	}
	diff := diffEnv(env, dumped)
	shell, _ := shellFromName("bash")
	fmt.Println(diff.toShell(shell))
	return nil
}
