		if (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_' || c == '.' {
			i++
			continue
		}
		break
	}
	if i == 0 {
		return "", "", false
	}
	key := s[:i]
	rest := strings.TrimLeft(s[i:], " \t")
	// after key spaces, the next char may be anything? Actually key scan
	// stopped at the first non-key char; if that char is not space/tab/'='
	// (handled by TrimLeft only removing space/tab), validation fails.
	// The TrimLeft above would leave e.g. '-' in place, so check '='.
	if rest == "" || rest[0] != '=' {
		return "", "", false
	}
	rest = rest[1:]
	rest = strings.TrimLeft(rest, " \t")
	return key, rest, true
}

// analyseValue returns (innerOrProcessedCandidate, isQuoted, quote, invalid, unclosed)
// For quoted values the returned value is the inner content.
func (p *dotenvParser) analyseValue(raw string) (string, bool, byte, bool, bool) {
	return p.analyseValueCommon(raw, true)
}

func (p *dotenvParser) analyseValueMultiline(raw string) (string, bool, byte, bool, bool) {
	return p.analyseValueCommon(raw, false)
}

func (p *dotenvParser) analyseValueCommon(raw string, allowComment bool) (string, bool, byte, bool, bool) {
	if raw == "" {
		return "", false, 0, false, false
	}
	if raw[0] != '\'' && raw[0] != '"' {
		// unquoted
		v := raw
		if idx := strings.Index(v, "#"); idx >= 0 {
			v = v[:idx]
		}
		v = strings.TrimRight(v, " \t")
		if strings.Contains(v, " ") || strings.Contains(v, "\t") {
			return "", false, 0, true, false
		}
		return v, false, 0, false, false
	}
	q := raw[0]
	trimmed := strings.TrimRight(raw, " \t")
	last := strings.LastIndexByte(trimmed, q)
	if last <= 0 {
		// No closing quote on this line
		return "", true, q, false, true
	}
	after := trimmed[last+1:]
	afterTrim := strings.TrimLeft(after, " \t")
	if afterTrim == "" || (allowComment && strings.HasPrefix(afterTrim, "#")) {
		return trimmed[1:last], true, q, false, false
	}
	if after == afterTrim {
		// attached extra like 'a'extra -> treated as an unquoted value
		v := raw
		if idx := strings.Index(v, "#"); idx >= 0 {
			// For a value containing a quote, a '#' that is inside what
			// would be quotes is ambiguous; the original cut at the
			// quote-aware comment, but attached-extra values were kept
			// whole unless a comment follows a space. Keep simple: if
			// there is a quote before '#', keep as-is up to trimming.
			// Use raw up to # only when the # is not between quotes.
			// Here the opening quote has a closing quote before #, so
			// treat # as comment start.
			v = v[:idx]
		}
		v = strings.TrimRight(v, " \t")
		if strings.Contains(v, " ") || strings.Contains(v, "\t") {
			return "", false, 0, true, false
		}
		return v, false, 0, false, false
	}
	// after starts with whitespace and then non-comment content -> invalid,
	// unless that content is itself a quoted segment ending at the last
	// quote, which is already handled by last-quote logic when trimmed
	// ends with the quote. Since last is the final quote in trimmed, if
	// trimmed does not end with q, this is the invalid case.
	return "", false, 0, true, false
}

func (p *dotenvParser) doubleQuoted(s string) string {
	// Two-backslash + n / r collapse first (mirrors observed behaviour
	// for \\n and \\r sequences).
	s = strings.ReplaceAll(s, "\\\\n", "\n")
	s = strings.ReplaceAll(s, "\\\\r", "\r")
	// Unescape pass: \n, \r are real escapes; other escaped chars drop
	// the backslash, except \$ which is preserved for the expansion pass.
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\\' && i+1 < len(s) {
			n := s[i+1]
			switch n {
			case 'n':
				sb.WriteByte('\n')
				i++
			case 'r':
				sb.WriteByte('\r')
				i++
			case '$':
				sb.WriteString("\\$")
				i++
			case '\n':
				sb.WriteString("\\\n")
				i++
			case '\r':
				sb.WriteString("\\\r")
				i++
			default:
				if n >= 32 && n <= 126 {
					sb.WriteByte(n)
					i++
				} else {
					sb.WriteByte('\\')
				}
			}
			continue
		}
		sb.WriteByte(c)
	}
	s = sb.String()
	s = p.expand(s)
	return s
}
EOF
"}

