{"command":"cat > internal/cmd/cmd_watch.go <<'EOF'
package cmd

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

func getWatches(env Env) (FileTimes, error) {
	if v, ok := env["DIRENV_WATCHES"]; ok {
		return unmarshalFileTimes(v)
	}
	return newEmptyFileTimes(), nil
}

func outputWatches(env Env, shell Shell, times FileTimes) string {
	outEnv := Env{"DIRENV_WATCHES": times.marshalString()}
	_ = env
	return outEnv.ToShell(shell)
}

func cmdWatch(env Env, args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("a path is required to add to the list of watches")
	}
	shell, err := shellFromName(args[0])
	if err != nil {
		return err
	}
	times, err := getWatches(env)
	if err != nil {
		return err
	}
	for _, p := range args[1:] {
		times.updateFromFile(p)
	}
	fmt.Print(outputWatches(env, shell, times))
	return nil
}

func cmdWatchDir(env Env, args []string) error {
	if len(args) < 2 {
		return fmt.Errorf("a directory is required to add to the list of watches")
	}
	shell, err := shellFromName(args[0])
	if err != nil {
		return err
	}
	dir := args[1]
	if _, err := os.Stat(dir); err != nil {
		return fmt.Errorf("dir '%s' does not exist", dir)
	}
	times, err := getWatches(env)
	if err != nil {
		return err
	}
	err = filepath.Walk(dir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		abs := absPath(path)
		times.update(abs, info.ModTime().Unix(), true)
		return nil
	})
	if err != nil {
		return fmt.Errorf("failed to recursively watch dir '%s': %w", dir, err)
	}
	fmt.Print(outputWatches(env, shell, times))
	return nil
}

func cmdWatchList(env Env, args []string) error {
	shellName := "bash"
	if len(args) > 0 {
		shellName = args[0]
	}
	shell, err := shellFromName(shellName)
	if err != nil {
		return err
	}
	times, err := getWatches(env)
	if err != nil {
		return err
	}
	reader := bufio.NewReader(stdinReader())
	lineNo := 0
	for {
		line, err := reader.ReadString('\n')
		if err != nil {
			break
		}
		lineNo++
		line = strings.TrimSuffix(line, "\n")
		parts := strings.SplitN(line, " ", 2)
		if len(parts) != 2 {
			return fmt.Errorf("line %d: expected to contain two elements", lineNo)
		}
		mtime, err := strconv.Atoi(parts[0])
		if err != nil {
			return fmt.Errorf("line %d: %w", lineNo, err)
		}
		times.update(parts[1], int64(mtime), true)
	}
	fmt.Print(outputWatches(env, shell, times))
	return nil
}

func cmdWatchPrint(env Env, args []string) error {
	times, err := getWatches(env)
	if err != nil {
		return err
	}
	sep := "\n"
	if len(args) > 0 && args[0] == "--null" {
		sep = "\x00"
	}
	for _, ft := range times.slice() {
		fmt.Print(ft.Path + sep)
	}
	return nil
}

func cmdCurrent(env Env, args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("missing PATH argument")
	}
	path := absPath(args[0])
	times, err := getWatches(env)
	if err != nil {
		return err
	}
	ft, ok := times.find(path)
	if !ok {
		return fmt.Errorf("File %q is unknown", path)
	}
	return ft.check()
}

var _ io.Reader
EOF
"}

