{"command":"cat > internal/cmd/cmd_check_required.go <<'EOF'
package cmd

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

func cmdCheckRequired(cfg *Config, env Env, args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("a shell name is required")
	}
	if len(args) == 1 {
		return fmt.Errorf("an envrc path is required")
	}
	if len(args) == 2 {
		return fmt.Errorf("at least one file path is required")
	}
	shell, err := shellFromName(args[0])
	if err != nil {
		return err
	}
	envrcArg := args[1]
	files := args[2:]

	// validation first
	for _, f := range files {
		if filepath.IsAbs(f) {
			fmt.Printf("log_error %s;\n", bashEscape(fmt.Sprintf("require_allowed: path must be relative: %s", f)))
			fmt.Printf("exit %d;\n", 1)
			return nil
		}
		if strings.Contains(f, "..") {
			fmt.Printf("log_error %s;\n", bashEscape(fmt.Sprintf("require_allowed: path must not contain '..': %s", f)))
			fmt.Printf("exit %d;\n", 1)
			return nil
		}
	}

	envrcPath := absPath(envrcArg)
	envrcDir := filepath.Dir(envrcPath)
	envrcHash := hashString(envrcPath + "\n")

	var unapproved []string
	for _, f := range files {
		full := filepath.Join(envrcDir, f)
		content, err := os.ReadFile(full)
		if err != nil {
			unapproved = append(unapproved, f)
			continue
		}
		fileHash := fileHashHex(full, content)
		allowedPath := filepath.Join(cfg.dataDir, "allowed-required", envrcHash, fileHash)
