{"command":"cat > internal/cmd/cmd_edit.go <<'EOF'
package cmd

import (
	"fmt"
	"os"
	osexec "os/exec"
	"path/filepath"
	"strings"
)

func findEditor(env Env) (string, error) {
	if v := env["EDITOR"]; v != "" {
		return v, nil
	}
	logError("$EDITOR not found.")
	candidates := [][]string{
		{"editor"},
		{"subl", "-w"},
		{"mate", "-w"},
		{"open", "-t", "-W"},
		{"nano"},
		{"vim"},
		{"emacs"},
	}
	for _, cand := range candidates {
		if _, err := osexec.LookPath(cand[0]); err == nil {
			return strings.Join(cand, " "), nil
		}
	}
	return "", fmt.Errorf("could not find a default editor in the PATH")
}

func cmdEdit(cfg *Config, env Env, args []string) error {
	var rcPath string
	if len(args) > 0 {
		arg := args[0]
		if info, err := os.Stat(arg); err == nil && info.IsDir() {
			rcPath = filepath.Join(arg, ".envrc")
		} else {
			rcPath = arg
		}
	} else {
		wd, err := os.Getwd()
		if err != nil {
			return err
		}
		rc := findRC(wd, cfg)
		if rc == nil {
			return fmt.Errorf(".envrc or .env not found. Use `direnv edit .` to create a new .envrc in the current directory")
		}
		rcPath = rc.path
	}

	editor, err := findEditor(env)
	if err != nil {
		return err
	}

	before := getFileTime(absPath(rcPath))
	shellCmd := editor + " " + bashEscape(rcPath)
	cmd := osexec.Command(cfg.bashPath, "-c", shellCmd)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Env = env.toGoEnv()
	if err := cmd.Run(); err != nil {
		return err
	}
	after := getFileTime(absPath(rcPath))
	if after != before {
		// Allow the (possibly new) RC that this file belongs to.
		return cmdAllow(cfg, env, []string{rcPath})
	}
	return nil
}
EOF
"}

