{"command":"cat > internal/cmd/cmd_fetchurl.go <<'EOF'
package cmd

import (
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"syscall"
	"unsafe"
)

type sriHash struct {
	raw  string
	algo string
	hash []byte
}

func parseSRI(s string) (*sriHash, error) {
	parts := strings.SplitN(s, "-", 2)
	if len(parts) != 2 {
		return nil, fmt.Errorf("sri: not a hash %s", s)
	}
	algo := parts[0]
	switch algo {
	case "sha256", "sha384", "sha512":
	default:
		return nil, fmt.Errorf("sri: unsupported algo %s", algo)
	}
	b, err := base64.StdEncoding.DecodeString(parts[1])
	if err != nil {
		return nil, err
	}
	return &sriHash{raw: s, algo: algo, hash: b}, nil
}

func isTerminal(f *os.File) bool {
	// TCGETS ioctl check (Linux).
	var termios [64]byte
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), uintptr(0x5401), uintptr(unsafe.Pointer(&termios[0])))
	return errno == 0
}

func fetchURL(cfg *Config, url string, integrity string, hasIntegrity bool) (string, string, error) {
	casDir := filepath.Join(cfg.cacheDir, "cas")
	var expected *sriHash
	var dest string
	if hasIntegrity {
		var err error
		expected, err = parseSRI(integrity)
		if err != nil {
			return "", "", err
		}
		dest = filepath.Join(casDir, hex.EncodeToString(expected.hash))
		if _, err := os.Stat(dest); err == nil {
			return dest, integrity, nil
		}
	}

	if err := os.MkdirAll(casDir, 0755); err != nil {
		return "", "", err
	}
	tmpFile, err := os.CreateTemp(casDir, "tmp")
	if err != nil {
		return "", "", err
	}
	tmpName := tmpFile.Name()
	renamed := false
	defer func() {
		if err := tmpFile.Close(); err != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to close temp file: %s\n", err)
		}
		if err := os.Remove(tmpName); err != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to remove temp file %s: %s\n", tmpName, err)
		}
		_ = renamed
	}()

	resp, err := http.Get(url)
	if err != nil {
		return "", "", err
	}
	defer resp.Body.Close()
	if resp.StatusCode != 200 {
		return "", "", fmt.Errorf("expected status code 200 but got %d", resp.StatusCode)
	}
	h := sha256.New()
	w := io.MultiWriter(tmpFile, h)
	if _, err := io.Copy(w, resp.Body); err != nil {
		return "", "", err
	}
	sum := h.Sum(nil)
	computed := "sha256-" + base64.StdEncoding.EncodeToString(sum)
	if hasIntegrity && integrity != computed {
		return "", "", fmt.Errorf("hash mismatch. Expected '%s' but got '%s'", integrity, computed)
	}
	if !hasIntegrity || expected != nil {
		dest = filepath.Join(casDir, hex.EncodeToString(sum))
	}
	if _, err := os.Stat(dest); err == nil {
		return dest, computed, nil
	}
	// Close before rename; the deferred cleanup will then report the
	// same two warnings the original does after a successful rename.
	_ = tmpFile.Close()
	if err := os.Rename(tmpName, dest); err != nil {
		return "", "", err
	}
	renamed = true
	if err := os.Chmod(dest, 0500); err != nil {
		return "", "", err
	}
	return dest, computed, nil
}

func cmdFetchURL(cfg *Config, env Env, args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("missing URL argument")
	}
	url := args[0]
	integrity := ""
	hasIntegrity := false
	if len(args) > 1 {
		integrity = args[1]
		hasIntegrity = true
	}
	path, computed, err := fetchURL(cfg, url, integrity, hasIntegrity)
	if err != nil {
		return err
	}
	if hasIntegrity {
		fmt.Println(path)
		return nil
	}
	if isTerminal(os.Stdout) {
		fmt.Printf("Found hash: %s\n\nInvoke fetchurl again with the hash as an argument to get the disk location:\n\n  direnv fetchurl %q %q\n  #=> %s\n", computed, url, computed, path)
	} else {
		fmt.Println(computed)
	}
	return nil
}
EOF
"}

