import subprocess, os, re, json, base64, zlib
ORIG="/workspace/executable"; OURS="/tmp/ourbin"
vals={"KEY_A":"hello","KEY_B":"a'b\nc\td $e \"f\" \\g","EMPTY":"","NUM":"123","UNICODE":"héllo→","PATH":"/a:/b c:/d","ctrl":"\x01"}
def run(bin,shell):
    e={"HOME":"/tmp/testhome2","PATH":"/usr/bin"}; e.update(vals)
    r=subprocess.run([bin,"dump",shell], cwd="/tmp", env=e, capture_output=True, text=True)
    return r.returncode, r.stdout, r.stderr
def norm(shell,out):
    if shell in ("bash","zsh","fish","tcsh","pwsh"):
        parts=[p for p in out.strip().split(";") if p]
        return sorted(parts)
    if shell in ("elvish","murex","json"):
        try: return json.loads(out)
        except: return out
    if shell=="vim":
        return sorted(out.strip().splitlines())
    if shell=="systemd":
        return sorted([l for l in out.splitlines() if l])
    if shell=="gha":
        # split blocks by delimiter line pattern. Use regex
        blocks=re.split(r"\n(?=[A-Z_]+<<ghadelimiter_)", out.strip())
        cleaned=[]
        for b in blocks:
            b=re.sub(r"ghadelimiter_[0-9a-f]+","DELIM",b)
            cleaned.append(b)
        return sorted(cleaned)
    if shell=="gzenv":
        try: return json.loads(zlib.decompress(base64.urlsafe_b64decode(out.strip())))
        except Exception as ex: return ("decode err",ex,out)
    return out
for sh in ["bash","zsh","fish","tcsh","elvish","pwsh","murex","json","vim","gha","gzenv","systemd"]:
    ro=run(ORIG,sh); ru=run(OURS,sh)
    no,nou=norm(sh,ro[1]), norm(sh,ru[1])
