{"command":"cat > internal/cmd/cmd_edit.go <<'EOF'
package cmd

import (
	"fmt"
	"os"
	osexec "os/exec"
	"path/filepath"
	"strings"
)

func findEditor(env Env) (string, error) {
	if v := env["EDITOR"]; v != "" {
		return v, nil
	}
	logError("$EDITOR not found.")
	candidates := [][]string{
		{"editor"},
		{"subl", "-w"},
		{"mate", "-w"},
		{"open", "-t", "-W"},
		{"nano"},
		{"vim"},
		{"emacs"},
	}
	for _, cand := range candidates {
		if _, err := osexec.LookPath(cand[0]); err == nil {
			return strings.Join(cand, " "), nil
		}
	}
	return "", fmt.Errorf("could not find a default editor in the PATH")
}

func allowRCOnly(cfg *Config, rc *RC) error {
	_ = os.Remove(rc.denyPath)
	if err := os.MkdirAll(filepath.Dir(rc.allowPath), 0755); err != nil {
		return err
	}
	return os.WriteFile(rc.allowPath, []byte(rc.path+"\n"), 0644)
}

func cmdEdit(cfg *Config, env Env, args []string) error {
	wd, err := os.Getwd()
	if err != nil {
		return err
	}
	beforeFound := findRC(wd, cfg)
	var beforeTimes *FileTimes
	if beforeFound != nil {
		l := make([]FileTime, len(beforeFound.times.slice()))
		copy(l, beforeFound.times.slice())
		ft := FileTimes{list: &l}
		beforeTimes = &ft
	}

	var rcPath string
	if len(args) > 0 {
		arg := args[0]
		if info, err := os.Stat(arg); err == nil && info.IsDir() {
			rcPath = filepath.Join(arg, ".envrc")
		} else {
			rcPath = arg
		}
	} else {
		if beforeFound == nil {
			return fmt.Errorf(".envrc or .env not found. Use `direnv edit .` to create a new .envrc in the current directory")
		}
		rcPath = beforeFound.path
	}

	editor, err := findEditor(env)
	if err != nil {
		return err
	}

	shellCmd := editor + " " + bashEscape(rcPath)
	cmd := osexec.Command(cfg.bashPath, "-c", shellCmd)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Env = env.toGoEnv()
	if err := cmd.Run(); err != nil {
		return err
	}

	if beforeTimes == nil {
		absRc := absPath(rcPath)
		searchDir := absRc
		if info, err := os.Stat(absRc); err != nil || !info.IsDir() {
			searchDir = filepath.Dir(absRc)
		}
		if afterRC := findRC(searchDir, cfg); afterRC != nil {
			return allowRCOnly(cfg, afterRC)
		}
		return nil
	}

	if err := beforeTimes.check(); err != nil {
		if refreshed := newRC(beforeFound.path, cfg, nil); refreshed != nil {
			return allowRCOnly(cfg, refreshed)
		}
	}
	return nil
}
EOF
