package cmd

import (
	"fmt"
	"os"
	"path/filepath"
)

type FileTime struct {
	Path    string `json:"path"`
	ModTime int64  `json:"modtime"`
	Exists  bool   `json:"exists"`
}

type FileTimes struct {
	list *[]FileTime
}

func newEmptyFileTimes() FileTimes {
	l := []FileTime{}
	return FileTimes{list: &l}
}

func (times FileTimes) slice() []FileTime {
	if times.list == nil || *times.list == nil {
		return []FileTime{}
	}
	return *times.list
}

func (times FileTimes) marshalString() string {
	s, _ := marshal(times.slice())
	return s
}

func unmarshalFileTimes(data string) (FileTimes, error) {
	var l []FileTime
	if err := unmarshal(data, &l); err != nil {
		return FileTimes{}, err
	}
	return FileTimes{list: &l}, nil
}

func getFileTime(path string) FileTime {
	mt, ok := getLatestStat(path)
	if !ok {
		return FileTime{Path: path, ModTime: 0, Exists: false}
	}
	return FileTime{Path: path, ModTime: mt, Exists: true}
}

func absPath(path string) string {
	abs, err := filepath.Abs(path)
	if err != nil {
		return filepath.Clean(path)
	}
	return abs
}

func (times *FileTimes) update(path string, modTime int64, exists bool) {
	abs := absPath(path)
	if times.list == nil {
		l := []FileTime{}
		times.list = &l
	}
	for i := range *times.list {
		if (*times.list)[i].Path == abs {
			(*times.list)[i].ModTime = modTime
			(*times.list)[i].Exists = exists
			return
		}
	}
	*times.list = append(*times.list, FileTime{Path: abs, ModTime: modTime, Exists: exists})
}

func (times *FileTimes) updateFromFile(path string) {
	ft := getFileTime(absPath(path))
	times.update(ft.Path, ft.ModTime, ft.Exists)
}

func (times FileTimes) find(path string) (FileTime, bool) {
	for _, ft := range times.slice() {
		if ft.Path == path {
			return ft, true
		}
	}
	return FileTime{}, false
}

func (times FileTimes) check() error {
	for _, ft := range times.slice() {
		if err := ft.check(); err != nil {
			return err
		}
	}
	return nil
}

func (ft FileTime) check() error {
	mt, ok := getLatestStat(ft.Path)
	gone := !ok && ft.Exists
	appeared := ok && !ft.Exists
	stale := ok && ft.Exists && mt != ft.ModTime
	if gone {
		debugLogf("Stat Check: %s: gone", ft.Path)
		return fmt.Errorf("File %q is missing (Stat)", ft.Path)
	}
	if appeared {
		debugLogf("Check: %s: appeared", ft.Path)
		return fmt.Errorf("File %q newly created", ft.Path)
	}
	if stale {
		debugLogf("Check: %s: stale (stat: %d, lastcheck: %d)", ft.Path, mt, ft.ModTime)
		return fmt.Errorf("File %q has changed", ft.Path)
	}
	debugLogf("Check: %s: up to date", ft.Path)
	return nil
}

func getLatestStat(path string) (int64, bool) {
	linfo, lerr := os.Lstat(path)
	if lerr != nil {
		debugLogf("getLatestStat,Lstat: %s: error: %s", path, lerr)
		return 0, false
	}
	sinfo, serr := os.Stat(path)
	if serr != nil {
		debugLogf("getLatestStat,Stat: %s: error: %s (Lstat time: %d)", path, serr, linfo.ModTime().Unix())
		return linfo.ModTime().Unix(), false
	}
	lt := linfo.ModTime().Unix()
	st := sinfo.ModTime().Unix()
	if lt > st {
		debugLogf("getLatestStat: %s: Lstat: %d, Stat: %d -> preferring Lstat", path, lt, st)
		return lt, true
	}
	debugLogf("getLatestStat: %s: Lstat: %d, Stat: %d -> preferring Stat", path, lt, st)
	return st, true
}
EOF
